/**
 * OnlyRoundsLogo / OnlyRoundsLogoMark — brand marks for the OnlyRounds
 * sub-brand under Apna.
 *
 * Two exports so the sidebar (and anyone else) can swap between a full
 * lockup and an icon-only glyph without clipping tricks:
 *   - <OnlyRoundsLogo />      → 248×42 · mark + wordmark
 *   - <OnlyRoundsLogoMark />  → 39×42  · mark only (the O-ring glyph)
 *
 * The gradients are the designer-approved sRGB stops exported directly
 * from the Figma source. Stops are literal hex because the exported SVGs
 * are final artwork, not theme-reactive surfaces — keeping the glyph
 * consistent with brand guidance across themes.
 *
 * Gradient IDs are namespaced (`or-mark-*` / `or-logo-*`) so both
 * components can render on the same page without defs colliding.
 */

import { cn } from "@/lib/utils"

// Stop palette — single source for both components.
const STOPS = {
  green300: "#74D7AE",
  green400: "#3EBA8D",
  gold300:  "#FFD975",
  sky400:   "#7BB9E5",
} as const

// Reusable gradient defs. Accepts an id prefix so two copies of the defs
// can coexist on the page (one for the mark, one for the full lockup).
function MarkGradients({ prefix }: { prefix: string }) {
  return (
    <defs>
      <linearGradient
        id={`${prefix}-0`}
        x1="9.67724" y1="5.18445" x2="2.28946" y2="32.7183"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor={STOPS.green300} />
        <stop offset="1" stopColor={STOPS.sky400} />
      </linearGradient>
      <linearGradient
        id={`${prefix}-1`}
        x1="28.3601" y1="28.3822" x2="38.7089" y2="28.3822"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor={STOPS.gold300} />
        <stop offset="1" stopColor={STOPS.green400} />
      </linearGradient>
      <linearGradient
        id={`${prefix}-2`}
        x1="32.6782" y1="29.0672" x2="36.8885" y2="31.495"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor={STOPS.sky400} />
        <stop offset="1" stopColor={STOPS.gold300} />
      </linearGradient>
      <linearGradient
        id={`${prefix}-3`}
        x1="13.4626" y1="2.38751" x2="27.0854" y2="15.9916"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor={STOPS.gold300} />
        <stop offset="1" stopColor={STOPS.green300} stopOpacity="0.99" />
      </linearGradient>
      <linearGradient
        id={`${prefix}-4`}
        x1="5.89046" y1="13.4828" x2="1.11813" y2="10.3991"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor={STOPS.sky400} />
        <stop offset="1" stopColor={STOPS.green300} />
      </linearGradient>
      <linearGradient
        id={`${prefix}-5`}
        x1="35.7645" y1="11.0953" x2="23.256" y2="33.6919"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor={STOPS.sky400} />
        <stop offset="1" stopColor={STOPS.gold300} />
      </linearGradient>
      <linearGradient
        id={`${prefix}-6`}
        x1="15.632" y1="30.0551" x2="18.6601" y2="41.3405"
        gradientUnits="userSpaceOnUse"
      >
        <stop stopColor={STOPS.green300} />
        <stop offset="1" stopColor={STOPS.gold300} />
      </linearGradient>
    </defs>
  )
}

// The 7 faceted mark paths — reused by both components (the full logo
// keeps the mark in the same 0–39 X band, then paints the wordmark to
// its right).
