/**
 * Icon-only variant — just the O-ring mark. Use in the collapsed sidebar
 * rail, favicons, compact app chrome.
 *
 * Intrinsic ratio 39:42 (near-square). No wordmark → safe at 24–32 px.
 */
export function OnlyRoundsLogoMark({
  className,
  ...props
}: React.SVGProps<SVGSVGElement>) {
  return (
    <svg
      viewBox="0 0 39 42"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-label="OnlyRound AI"
      role="img"
      className={cn("h-6 w-auto", className)}
      {...props}
    >
      <MarkPaths prefix="or-mark" />
      <MarkGradients prefix="or-mark" />
    </svg>
  )
}
